create or replace function public.phase1c_assert(condition boolean,message text) returns void language plpgsql as $$ begin if condition is distinct from true then raise exception 'FALLO: %',message; end if; end $$;
begin; set local role authenticated; select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000101',true);
select public.phase1c_assert(exists(select 1 from public.clients where id='30000000-0000-0000-0000-000000000001') and not exists(select 1 from public.clients where organization_id='20000000-0000-0000-0000-000000000001'),'owner isolate clients');
select public.phase1c_assert(exists(select 1 from public.workers where id='40000000-0000-0000-0000-000000000001') and not exists(select 1 from public.workers where organization_id='20000000-0000-0000-0000-000000000001'),'owner isolate workers'); rollback;
begin; set local role authenticated; select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000102',true);
select public.phase1c_assert((public.update_worker_with_revision('40000000-0000-0000-0000-000000000001',(select revision from public.workers where id='40000000-0000-0000-0000-000000000001'),'{"phone":"600111222"}'::jsonb)).phone='600111222','controlled admin update');
select public.phase1c_assert((select count(*) from public.worker_audit_log where worker_id='40000000-0000-0000-0000-000000000001' and actor_id=auth.uid() and action='updated')>=1,'controlled update audit'); rollback;
begin; set local role authenticated; select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000103',true);
select public.phase1c_assert(exists(select 1 from public.organizations where id='10000000-0000-0000-0000-000000000001') and not exists(select 1 from public.clients where organization_id='10000000-0000-0000-0000-000000000001') and not exists(select 1 from public.workers where organization_id='10000000-0000-0000-0000-000000000001'),'employee restricted'); rollback;
begin; set local role authenticated; select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000104',true); select public.phase1c_assert(not exists(select 1 from public.clients),'pending blocked'); rollback;
begin; set local role authenticated; select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000105',true); select public.phase1c_assert(not exists(select 1 from public.organizations),'inactive blocked'); rollback;
do $$ begin begin delete from public.organization_members where organization_id='10000000-0000-0000-0000-000000000001' and user_id='00000000-0000-0000-0000-000000000101'; raise exception 'FALLO: last owner removed'; exception when others then if position('al menos un owner activo' in sqlerrm)=0 then raise; end if; end; end $$;
drop function public.phase1c_assert(boolean,text); select 'phase1c_security: OK' result;
